
package com.hamidprojectapp.gpsspeedometer;

import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.app.Service;
import android.content.Intent;
import android.content.pm.ServiceInfo;
import android.os.Build;
import android.os.IBinder;

public class TripTrackingService extends Service {

    private static final String CHANNEL_ID = "gps_tracking_channel";
        private static final int NOTIFICATION_ID = 1001;

            public static final String ACTION_START =
                        "com.hamidprojectapp.gpsspeedometer.START_TRACKING";

                            public static final String ACTION_STOP =
                                        "com.hamidprojectapp.gpsspeedometer.STOP_TRACKING";

                                            @Override
                                                public void onCreate() {
                                                        super.onCreate();
                                                                createNotificationChannel();
                                                                    }

                                                                        @Override
                                                                            public int onStartCommand(Intent intent, int flags, int startId) {

                                                                                    if (intent != null && ACTION_STOP.equals(intent.getAction())) {
                                                                                                stopForeground(true);
                                                                                                            stopSelf();
                                                                                                                        return START_NOT_STICKY;
                                                                                                                                }

                                                                                                                                        Notification notification = buildNotification();

                                                                                                                                                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                                                                                                                                                            startForeground(
                                                                                                                                                                                NOTIFICATION_ID,
                                                                                                                                                                                                    notification,
                                                                                                                                                                                                                        ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION
                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                        startForeground(NOTIFICATION_ID, notification);
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                        return START_STICKY;
                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                private void createNotificationChannel() {
                                                                                                                                                                                                                                                                                        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {

                                                                                                                                                                                                                                                                                                    NotificationChannel channel = new NotificationChannel(
                                                                                                                                                                                                                                                                                                                        CHANNEL_ID,
                                                                                                                                                                                                                                                                                                                                            "GPS Sedang Berjalan",
                                                                                                                                                                                                                                                                                                                                                                NotificationManager.IMPORTANCE_LOW
                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                        channel.setDescription(
                                                                                                                                                                                                                                                                                                                                                                                                            "Notifikasi saat perjalanan GPS sedang direkam"
                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                    NotificationManager manager =
                                                                                                                                                                                                                                                                                                                                                                                                                                                        getSystemService(NotificationManager.class);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    manager.createNotificationChannel(channel);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private Notification buildNotification() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return new Notification.Builder(this, CHANNEL_ID)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setContentTitle("GPS Speedometer")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setContentText("Perjalanan sedang direkam")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setSmallIcon(android.R.drawable.ic_menu_mylocation)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setOngoing(true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setCategory(Notification.CATEGORY_SERVICE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .build();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    @Override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        public IBinder onBind(Intent intent) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    